40	/**
41	 * A generic implementation of {@link RocksDBStore.ColumnFamilyAccessor} that supports dual-column-family
42	 * upgrade scenarios. This class manages two column families:
43	 * <ul>
44	 *   <li>oldColumnFamily: contains legacy data in the old format</li>
45	 *   <li>newColumnFamily: contains data in the new format</li>
46	 * </ul>
47	 *
48	 * When reading, it first checks the new column family, then falls back to the old column family
49	 * and converts values on-the-fly using the provided conversion function.
50	 */
51	class DualColumnFamilyAccessor implements RocksDBStore.ColumnFamilyAccessor {
52	
53	    private final ColumnFamilyHandle oldColumnFamily;
54	    private final ColumnFamilyHandle newColumnFamily;
55	    private final Function<byte[], byte[]> valueConverter;
56	    private final RocksDBStore store;
57	
58	    /**
59	     * Constructs a DualColumnFamilyAccessor.
60	     *
61	     * @param oldColumnFamily the column family containing legacy data
62	     * @param newColumnFamily the column family for new format data
63	     * @param valueConverter  function to convert old format values to new format
64	     * @param store           the RocksDBStore instance (for accessing position, context, and name)
65	     */
66	    DualColumnFamilyAccessor(final ColumnFamilyHandle oldColumnFamily,
67	                             final ColumnFamilyHandle newColumnFamily,
68	                             final Function<byte[], byte[]> valueConverter,
69	                             final RocksDBStore store) {
70	        this.oldColumnFamily = oldColumnFamily;
71	        this.newColumnFamily = newColumnFamily;
72	        this.valueConverter = valueConverter;
73	        this.store = store;
74	    }
75	
76	    @Override
77	    public void put(final DBAccessor accessor,
78	                    final byte[] key,
79	                    final byte[] value) {
80	        synchronized (store.position) {
81	            if (value == null) {
82	                try {
83	                    accessor.delete(oldColumnFamily, key);
84	                } catch (final RocksDBException e) {
85	                    throw new ProcessorStateException("Error while removing key from store " + store.name(), e);
86	                }
87	                try {
88	                    accessor.delete(newColumnFamily, key);
89	                } catch (final RocksDBException e) {
90	                    throw new ProcessorStateException("Error while removing key from store " + store.name(), e);
91	                }
92	            } else {
93	                try {
94	                    accessor.delete(oldColumnFamily, key);
95	                } catch (final RocksDBException e) {
96	                    throw new ProcessorStateException("Error while removing key from store " + store.name(), e);
97	                }
98	                try {
99	                    accessor.put(newColumnFamily, key, value);
100	                    StoreQueryUtils.updatePosition(store.position, store.context);
101	                } catch (final RocksDBException e) {
102	                    throw new ProcessorStateException("Error while putting key/value into store " + store.name(), e);
103	                }
104	            }
105	        }
106	    }
107	
108	    @Override
109	    public void prepareBatch(final List<KeyValue<Bytes, byte[]>> entries,
110	                             final WriteBatchInterface batch) throws RocksDBException {
111	        for (final KeyValue<Bytes, byte[]> entry : entries) {
112	            Objects.requireNonNull(entry.key, "key cannot be null");
113	            addToBatch(entry.key.get(), entry.value, batch);
114	        }
115	    }
116	
117	    @Override
118	    public byte[] get(final DBAccessor accessor, final byte[] key)
119	        throws RocksDBException {
120	        return get(accessor, key, Optional.empty());
121	    }
122	
123	    @Override
124	    public byte[] get(final DBAccessor accessor, final byte[] key,
125	                      final ReadOptions readOptions)
126	        throws RocksDBException {
127	        return get(accessor, key, Optional.of(readOptions));
128	    }
129	
130	    private byte[] get(final DBAccessor accessor, final byte[] key,
131	                       final Optional<ReadOptions> readOptions)
132	        throws RocksDBException {
133	        final byte[] valueInNewFormat = readOptions.isPresent()
134	                ? accessor.get(newColumnFamily, readOptions.get(), key)
135	                : accessor.get(newColumnFamily, key);
136	        if (valueInNewFormat != null) {
137	            return valueInNewFormat;
138	        }
139	
140	        final byte[] valueInOldFormat = readOptions.isPresent()
141	                ? accessor.get(oldColumnFamily, readOptions.get(), key)
142	                : accessor.get(oldColumnFamily, key);
143	        if (valueInOldFormat != null) {
144	            final byte[] convertedValue = valueConverter.apply(valueInOldFormat);
145	            // This does only work because the changelog topic contains correct data already.
146	            // For other format changes, we cannot take this short cut and can only migrate data
147	            // from old to new store on put().
148	            put(accessor, key, convertedValue);
149	            return convertedValue;
150	        }
151	
152	        return null;
153	    }
154	
155	    @Override
156	    public byte[] getOnly(final DBAccessor accessor, final byte[] key) throws RocksDBException {
157	        final byte[] valueInNewFormat = accessor.get(newColumnFamily, key);
158	        if (valueInNewFormat != null) {
159	            return valueInNewFormat;
160	        }
161	
162	        final byte[] valueInOldFormat = accessor.get(oldColumnFamily, key);
163	        if (valueInOldFormat != null) {
164	            return valueConverter.apply(valueInOldFormat);
165	        }
166	
167	        return null;
168	    }
