package org.apache.kafka.streams.state.internals;

import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.common.serialization.StringSerializer;
import org.apache.kafka.streams.errors.ProcessorStateException;

import org.rocksdb.ColumnFamilyHandle;
import org.rocksdb.RocksDBException;

import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Abstract base class for all {@link RocksDBStore.ColumnFamilyAccessor} implementations.
 * <p>
 * It manages the lifecycle status of the store and the committed changelog offsets in a dedicated
 * offsets column family. The {@code status} key tracks whether the store was cleanly closed
 * ({@code 0L}) or is currently open ({@code 1L}), which allows detecting an unclean shutdown when
 * the store is reopened. The committed offsets are keyed by {@link TopicPartition#toString()}.
 * <p>
 * The concrete behaviour of flushing the data column families is delegated to subclasses via
 * {@link #flush(RocksDBStore.DBAccessor, ColumnFamilyHandle)}.
 */
abstract class AbstractColumnFamilyAccessor implements RocksDBStore.ColumnFamilyAccessor {

    private final ColumnFamilyHandle offsetColumnFamilyHandle;
    private final AtomicBoolean storeOpen;

    private final StringSerializer stringSerializer = new StringSerializer();
    private final Serdes.LongSerde longSerde = new Serdes.LongSerde();
    private final byte[] statusKey = stringSerializer.serialize(null, "status");
    private final byte[] openState = longSerde.serializer().serialize(null, 1L);
    private final byte[] closedState = longSerde.serializer().serialize(null, 0L);

    AbstractColumnFamilyAccessor(final ColumnFamilyHandle offsetColumnFamilyHandle,
                                 final AtomicBoolean storeOpen) {
        this.offsetColumnFamilyHandle = offsetColumnFamilyHandle;
        this.storeOpen = storeOpen;
    }

    @Override
    public final void open(final RocksDBStore.DBAccessor accessor,
                           final boolean ignoreInvalidState) throws RocksDBException {
        final byte[] valueBytes = accessor.get(offsetColumnFamilyHandle, statusKey);
        if (ignoreInvalidState || valueBytes == null || Arrays.equals(valueBytes, closedState)) {
            // The store is either brand-new (empty), was cleanly closed, or we have been asked to
            // ignore an invalid state; mark the store as open.
            storeOpen.set(true);
            accessor.put(offsetColumnFamilyHandle, statusKey, openState);
        } else {
            throw new ProcessorStateException(
                "Invalid state during store open. Expected state to be either empty or closed");
        }
    }

    @Override
    public void close(final RocksDBStore.DBAccessor accessor) throws RocksDBException {
        accessor.put(offsetColumnFamilyHandle, statusKey, closedState);
        offsetColumnFamilyHandle.close();
    }

    @Override
    public final void commit(final RocksDBStore.DBAccessor accessor,
                             final Map<TopicPartition, Long> changelogOffsets) throws RocksDBException {
        for (final Map.Entry<TopicPartition, Long> entry : changelogOffsets.entrySet()) {
            final byte[] key = stringSerializer.serialize(null, entry.getKey().toString());
            if (entry.getValue() == null) {
                accessor.delete(offsetColumnFamilyHandle, key);
            } else {
                final byte[] value = longSerde.serializer().serialize(null, entry.getValue());
                accessor.put(offsetColumnFamilyHandle, key, value);
            }
        }
        flush(accessor, offsetColumnFamilyHandle);
    }

    @Override
    public final Long getCommittedOffset(final RocksDBStore.DBAccessor accessor,
                                         final TopicPartition partition) throws RocksDBException {
        final byte[] valueBytes = accessor.get(
            offsetColumnFamilyHandle,
            stringSerializer.serialize(null, partition.toString()));
        if (valueBytes != null) {
            return longSerde.deserializer().deserialize(null, valueBytes);
        }
        return null;
    }

    /**
     * Flush the data column families managed by this accessor together with the given offsets column family.
     */
    protected abstract void flush(final RocksDBStore.DBAccessor accessor,
                                  final ColumnFamilyHandle offsetColumnFamilyHandle) throws RocksDBException;
}
